import numpy as np
from itertools import combinations_with_replacement
def polybasis(deg):
    cols=[np.ones_like(t)]; names=['1']
    base={'t':t,'x':x,'v':v}
    for d in range(1,deg+1):
        for comb in combinations_with_replacement(['t','x','v'],d):
            col=np.ones_like(t)
            for c_ in comb: col=col*base[c_]
            cols.append(col); names.append(''.join(comb))
    return np.column_stack(cols),names
